///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        MaxTab_01.setSelectedTabIndex(1);
        await scwin.setCode();
        await scwin.getDate();
        const vCurDate = $c.ut.cGetToday("yyyymmdd");
        edt_TASK_DD.setValue(vCurDate);
        $c.cm.PanelToGroupBox(panel_Top);
        btn_RcvPrc.show("");
        //    fn_list_sync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05940.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

