///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name getDate
 * @description 익일영업일 가져옴
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getDate = async function() {
    const sbmOptions = {
        id : "sbm_dts_getDate",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_getDate=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    const sbmOptions = {
        id : "sbm_dts_ElwInst",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_ElwInst=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // alert("call");

};

/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    if (MaxTab_01.getSelectedTabIndex() === 1) {
        btn_RcvPrc.show("");
        txb_TDD_CLSPRC.setDisabled(false);
        if (!await scwin.checkForm("1")) {
            return;
        }
        url += "&TDD_CLSPRC=" + txb_TDD_CLSPRC.getValue();
        url += "&TASK_DD=" + edt_TASK_DD.getValue();
        //            url += "&CALND_DD=" + dts_getDate.NameString(1, "CALND_DD");
        url += "&SCREN_ID=" + "ULDSTF05940.xml";
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        const sbmOptions = {
            id : "sbm_dts_List_1",
            action : "/ElwListedReceive.do",
            ref : "",
            target : "dts_List_1=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    } else if (MaxTab_01.getSelectedTabIndex() === 2) {
        btn_RcvPrc.hide();
        txb_TDD_CLSPRC.setDisabled(true);
        url += "&TASK_DD=" + edt_TASK_DD.getValue();
        url += "&SCREN_ID=" + "ULDSTF05940.xml";
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        const sbmOptions = {
            id : "sbm_dts_List_2",
            action : "/ElwListedReceive.do",
            ref : "",
            target : "dts_List_2=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    }
};

/**
 * @method
 * @name packacpt
 * @description packacpt 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.packacpt = async function() {
    let dtsObj = scwin.getDataSet();

    // 해당이 아닌 항목을 체크 할 경우 화면에서 체크해야 함.
    for (let i = 1; i <= dtsObj.getRowCount(); i++) {
        if (dtsObj.getCellData(i, "CHECK") === "T") {
            if (dtsObj.getCellData(i, "KO_LST_REJ_YN") !== "해당") {
                await $c.win.alert("상장거부여부 항목에 [ 해당 ] 인 경우만 선택하고 저장할수 있습니다.");
                return;
            }
        }
    }
    if (!await scwin.checkForm("1")) {
        return;
    }
    if (txb_TDD_CLSPRC.getValue() !== dtsObj.getCellData(1, "TDD_CLSPRC")) {
        await $c.win.alert("[입력한 당일종가]와 [검색한 당일종가] 다릅니다. 다시 조회하시고 저장하세요.");
        txb_TDD_CLSPRC.focus();
        return;
    }
    const vSelectCnt = scwin.selectIsuCheckCnt(dtsObj);
    if (vSelectCnt === 0) {
        await $c.win.alert("[종목]을 선택하세요.");
        return;
    }
    scwin.procJob = ' 선택한 ' + vSelectCnt + '종목에대한  저장처리 ';
    const res = window.confirm($c.stf.getMessageParam('MSG-A006', scwin.procJob));
    if (res) {
        // dts_Isu.UserStatus(1) = TB_JOB_UPDATE;
        for (let i = 1; i <= dtsObj.getRowCount(); i++) {
            if (dtsObj.getCellData(i, "CHECK") === "T") {
                dtsObj.setCellData(i, "LIST_PROCS_STAT_CD", ELW_RECV_PROC_CD_02);
                dtsObj.setCellData(i, "TDD_CLSPRC", txb_TDD_CLSPRC.getValue());
                dtsObj.setCellData(i, "REG_EMP_NO", js_emp_no);
            }
        }

        // alert('[dtsObj]'+dtsObj.text);
        trs_Save.KeyName = "toinb_dataid4";
        if (MaxTab_01.getSelectedTabIndex() === 1) {
            trs_Save.KeyValue = "JSP(I:pInput=dts_List_1)";
        }
        const sbmOptions = {
            id : "sbm_trs_Save",
            action : "/ElwListedReceive.do",
            ref : "",
            target : "trs_Save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name openDetail
 * @description open Detail 처리
 * @param {Number} row 행 인덱스
 * @param {*} dtsObj dtsObj
 * @returns {void}
 * @hidden N
 */
scwin.openDetail = function(row, dtsObj) {
    scwin.setBzProcsNo(row, dtsObj);
    const vbzTpCd = dtsObj.getCellData(row, "LIST_BZ_TP_CD");
    $c.elw.fn_OpenDetailRecv(vbzTpCd);
};

/**
 * @method
 * @name getListBzTpCd
 * @description 추가상장신청시의 업무구분코드 가져오기
 * @param {String} str str
 * @returns {void}
 * @hidden N
 */
scwin.getListBzTpCd = function(str) {
    let val = '';
    if (str === LIST_BZ_TP_CD_002) {
        val = LIST_BZ_TP_CD_004;
    } else if (str === LIST_BZ_TP_CD_003) {
        val = LIST_BZ_TP_CD_005;
    }
    return val;
};

/**
 * @method
 * @name setBzProcsNo
 * @description set Bz Procs No 처리
 * @param {Object} obj 컴포넌트
 * @param {*} dtsObj dtsObj
 * @returns {void}
 * @hidden N
 */
scwin.setBzProcsNo = function(obj, dtsObj) {
    scwin.clickBzProcsNo = dtsObj.getCellData(Number(obj), "BZ_PROCS_NO");
    // alert("fn_setBzProcsNo():"+clickBzProcsNo);

};

/**
 * @method
 * @name getDataSet
 * @description get Data Set 처리
 * @returns {void}
 * @hidden N
 */
scwin.getDataSet = function() {
    let dtsObj;
    if (MaxTab_01.getSelectedTabIndex() === 1) {
        dtsObj = dts_List_1;
    } else if (MaxTab_01.getSelectedTabIndex() === 2) {
        dtsObj = dts_List_2;
    }
    return dtsObj;
};

/**
 * @method
 * @name selectIsuCheckCnt
 * @description select Isu Check Cnt 처리
 * @param {*} dtsObj dtsObj
 * @returns {void}
 * @hidden N
 */
scwin.selectIsuCheckCnt = function(dtsObj) {
    let k = 0;
    for (let i = 1; i <= dtsObj.getRowCount(); i++) {
        if (dtsObj.getCellData(i, "CHECK") === "T") {
            k++;
        }
    }
    return k;
};

/**
 * @method
 * @name checkForm
 * @description check Form 처리
 * @param {*} procTyp procTyp
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function(procTyp) {
    if (procTyp === "1") {
        if (txb_TDD_CLSPRC.getValue() === "") {
            await $c.win.alert("[당일종가]를 입력하세요.");
            txb_TDD_CLSPRC.focus();
            return false;
        }
    }
    return true;
};

/**
 * @method
 * @name excelDown
 * @description 정보를 excel로 다운 받는다.
 * @returns {void}
 * @hidden N
 */
scwin.excelDown = function() {
    if (MaxTab_01.getSelectedTabIndex() === 1) {
        $c.data.downloadGridViewExcel(grd_List_1, {fileName: "조기종료충족에 의한 상장거부처리", type: "8"});
    } else if (MaxTab_01.getSelectedTabIndex() === 2) {
        $c.data.downloadGridViewExcel(grd_List_2, {fileName: "조기종료충족에 의한 상장거부처리내역", type: "8"});
    }
};

/**
 * @method
 * @name grd_List_1_CanColumnPosChange
 * @description grd List 1 Can Column Pos Change 처리
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_List_1_CanColumnPosChange = function(row, colid) {
    return true;
};
